mapper.select:
select v.id, g.group_key as groupKey, g.group_name as groupName, v.option_value as optionValue, v.label_zh as labelZh, v.label_fr as labelFr, v.label_en as labelEn, v.sort_order as sortOrder, v.requires_extra_text as requiresExtraText, v.status, v.created_at as createdAt, v.updated_at as updatedAt from cm_option_values v inner join cm_option_groups g on g.id = v.group_id where g.manage_status = 'dynamic'
and g.group_key = #{groupKey}
order by g.sort_order, g.group_key, v.sort_order, v.option_value
